CREATE TABLE carteiras (
  id SERIAL PRIMARY KEY,
  saldo NUMERIC NOT NULL
);
BEGIN;
UPDATE carteiras SET saldo = saldo - 50 WHERE id = 1;
UPDATE carteiras SET saldo = saldo + 50 WHERE id = 2;
COMMIT;

